body.userscript:


//폼, smr_number등의 정보를 담는 변수





//새로 만든 요청이라면 Y







switch (name) {
    case "SAVE":
        doSave();
        break;
    case "APPROVAL_REQUEST":
        doApprovalRequest();
        break;
    case "BACK":
        doBack();
        break;
    case "RETURN_REQUEST":
        doReturnRequest();
        break
    case "RETURN_COMPLETE":
        doReturnComplete();
        break
    default:
        break;
}




// 채번 따서 $reqExtInfo에 채번넣고 기본셋팅
$(approver_grid_cont).hide();
initCertExtGrid();

//폼 셋팅
formObj.getInput("EXT_OUT_EXPECT_DATE").placeholder = Sepoa.cache.text.get('SPC_001.EXT_OUT_YYYYMMDD'); //반출년월일
formObj.getInput("EXT_IN_EXPECT_DATE").placeholder = Sepoa.cache.text.get('SPC_001.EXT_IN_YYYYMMDD'); //반입년월일

formObj.attachEvent('onChange', function(name, value) {
    if ($extInDateRollback) {
        return;
    }
    if (name == 'EXT_OUT_EXPECT_DATE') {
        applyExtInDateRange(true);
    } else if (name == 'EXT_IN_EXPECT_DATE') {
        onExtInExpectDateChange(value);
    }
});
$prevExtInExpectDate = toYmd(formObj.getValue('EXT_IN_EXPECT_DATE')) || '';
applyExtInDateRange(false);

//폼 셋팅
formObj.checkItem('REAL_FLAG');
formObj.setReadonly('REAL_FLAG', true);

if (sUtils.ux.getRootScreenID() == 'SPC_000') {
    var smrNumber = Sepoa.request.SMR_NUMBER || getDocumentNumber("SCE"); //채번
    $reqExtInfo.SMR_NUMBER = smrNumber;
    formObj.setValue('SMR_NUMBER', smrNumber);

    initBtn();
}




if (gridObj_title) {
    gridObj_title.innerHTML = '공동인증서 내역';
    gridObj_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
}
// SLM_501_2 재사용: CertExt 표시 컬럼만 남기고 헤더 라벨 변경
// 일자(DOC_NUMBER), 담당자(SEAL_MG_USER_NAME), 관리번호(SMD_NUMBER),
// 공동인증서명(SEAL_MG_SUBJECT), 설명(SUBJECT), 공동인증서대장(ATTACH_IMG)
var hideCols = ['SELECTED', 'SEAL_TYPE', 'REAL_FLAG', 'ATTACH2_IMG', 'ATTACH2_NO', 'MANAGE_IMG', 'MANAGE_NUMBER',
    'SEAL_MG_DEPT', 'SEAL_MG_DEPT_LOC', 'SEAL_MG_USER_ID', 'COUNT', 'DOWN_COUNT',
    'ACCEPT_FLAG', 'COMPLETE_FLAG', 'SMR_SEQ', 'ATTACH_NO'];
for (var i = 0; i < hideCols.length; i++) {
    try {
        var idx = gridObj.getColIndexById(hideCols[i]);
        if (idx >= 0) {
            gridObj.setColumnHidden(idx, true);
        }
    } catch (e) {}
}
try {
    gridObj.setColumnHidden(gridObj.getColIndexById('DOC_NUMBER'), false);
    gridObj.setColumnLabel(gridObj.getColIndexById('DOC_NUMBER'), '일자');
    gridObj.setColumnLabel(gridObj.getColIndexById('SEAL_MG_USER_NAME'), '담당자');
    gridObj.setColumnLabel(gridObj.getColIndexById('SMD_NUMBER'), '관리번호');
    gridObj.setColumnLabel(gridObj.getColIndexById('SEAL_MG_SUBJECT'), '공동인증서명');
    gridObj.setColumnLabel(gridObj.getColIndexById('SUBJECT'), '설명');
    gridObj.setColumnLabel(gridObj.getColIndexById('ATTACH_IMG'), '공동인증서대장');
} catch (e) {}
hideCertExtGrid(true);
hideAllGridButtons();




gridObj_btnObj.forEachBtn(function(btnId) {
    if (btnId) {
        gridObj_btnObj.showButton(btnId, false);
    }
});




var display = hide ? 'none' : '';
var gridAreaEl = (typeof GGeujmepNmujmedMez !== 'undefined' && GGeujmepNmujmedMez)
    ? GGeujmepNmujmedMez
    : $($sObject._vp).find('#GGeujmepNmujmedMez')[0];
var gridObjEl = (typeof YutgpXfdrGhpXfzREq !== 'undefined' && YutgpXfdrGhpXfzREq)
    ? YutgpXfdrGhpXfzREq
    : $($sObject._vp).find('#YutgpXfdrGhpXfzREq')[0];
if (gridAreaEl) {
    gridAreaEl.style.display = display;
}
if (gridObjEl) {
    gridObjEl.style.display = display;
}
if (hide) {
    var gridBtnEl = document.getElementById('GGeujmeoArxjmeFbFw')
        || $($sObject._vp).find('#GGeujmeoArxjmeFbFw')[0];
    if (gridBtnEl) {
        gridBtnEl.style.display = 'none';
    }
}




hideAllGridButtons();
var showGrid = (smrStatus == 'RW' || smrStatus == 'RR' || smrStatus == 'C');
hideCertExtGrid(!showGrid);
if (!showGrid) {
    return;
}
document.getElementById('GGeujmeoArxjmeFbFw').style.display = 'inline-block';
if (smrStatus == 'RW') {
    gridObj.setReadOnly(false);
    gridObj.setEditable(true);
    gridObj_btnObj.showButton('rowadd,gridsave', true);
} else {
    gridObj.setReadOnly(true);
    gridObj.setEditable(false);
}




btnObj.forEachBtn(function(btnId) {
    if (btnId) {
        btnObj.showButton(btnId, false);
    }
});




document.getElementById('GGeujmeXdkujmeKLSb').style.display = 'inline-block';




if (mode) editMode = mode;




// CertExt 상태 기반 버튼 제어 (doSelectNextModule / MANAGER 미사용)
// T 임시저장, I 결재진행, R 결재반려, RW 반출승인, RR 반입대기, C 완료
hideAllButtons();

if (editMode == 'APP' || ['APPR_TURN', 'APPR_DONE', 'APPR_REFER'].indexOf(editMode) > -1) {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    $(approver_grid_cont).hide();
    showButtonArea();
    updateCertExtGridBtn();
    return;
}

if (smrStatus == 'T') {
    formObj.hideItem('REJECT_REMARK');
    formObj.setViewMode(false);
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
    if (editMode != 'VIEW') {
        btnObj.showButton('save,approval_request', true);
    } else {
        btnObj.showButton('back', true);
    }
} else if (smrStatus == 'R') {
    formObj.showItem('REJECT_REMARK');
    formObj.setViewMode(false);
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
    if (editMode != 'VIEW') {
        btnObj.showButton('save,approval_request', true);
    } else {
        btnObj.showButton('back', true);
    }
} else if (smrStatus == 'I') {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
} else if (smrStatus == 'RW') {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
    // 신청현황에서 반입요청
    if (!fromTodo) {
        btnObj.showButton('return_request', true);
    } else {
        btnObj.showButton('back', true);
    }
} else if (smrStatus == 'RR') {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    // 처리대상(Todo): 뒤로가기 + 반입완료 / 신청현황: 뒤로가기
    btnObj.showButton('back', true);
    if (fromTodo) {
        btnObj.showButton('return_complete', true);
    }
} else if (smrStatus == 'C') {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
} else {
    formObj._apiConnector('detachAllEvents', []);
    formObj.setViewMode(true);
    btnObj.showButton('back', true);
}

showButtonArea();
updateCertExtGridBtn();




$reqExtInfo = {};
$documentList = {};
formObj.clear();
gridObj.clearAll();
moveFlag = flag;
editMode = mode;
// Todo(처리대상)에서 진입 시 flag === true
var fromTodo = (flag === true);

doServiceAjax('sepoa.svc.seal.SepoaReqCertExtService', 'CONNECTION', 'doSelectRequestInfo', {
    SMR_NUMBER: smrNumber
}, function(so) {
    if (so.status == 1) {
        var reqData = JSON.parse(so.result[0]);
        var reqExtInfo = reqData[0].REQ_EXT_INFO;
        var documentList = reqData[0].DOCUMENT_LIST || [];
        formObj.dataMapper(reqExtInfo, 'JSON');
        $reqExtInfo.SMR_NUMBER = reqExtInfo.SMR_NUMBER;
        $reqExtInfo.SUBJECT = reqExtInfo.SUBJECT;

        smrStatus = reqExtInfo.SMR_STATUS;

        for (var i in documentList) {
            var data = documentList[i];
            var maxRowId = dhx4.newId();
            gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
            gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(formatCertExtDate(data.ADD_DATE));
            gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(data.SMD_NUMBER);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ')).setValue(data.SMR_SEQ);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_USER_ID')).setValue(data.ADD_USER_ID || data.SEAL_MG_USER_ID);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_USER_NAME')).setValue(data.ADD_USER_NAME || '');
            gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_SUBJECT')).setValue(data.SEAL_MG_SUBJECT || '법인 공동인증서');
            gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(data.SUBJECT || '');
            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_NO')).setValue(data.ATTACH_NO || '');
            gridObj.showRow(maxRowId);
            if (data.ATTACH_NO) {
                gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
            }
            $documentList[data.SMD_NUMBER] = data;
        }

        if (smrStatus != "T" && smrStatus != "R" && editMode != "APP" && sUtils.workflow.check('ETL1683709519388')) {
            $(approver_grid_cont).show();
            doQueryApprover(reqExtInfo.SMR_NUMBER);
        } else {
            $(approver_grid_cont).hide();
        }

        initBtn(fromTodo, editMode);
        doChangeEditMode(editMode);
        $prevExtInExpectDate = toYmd(formObj.getValue('EXT_IN_EXPECT_DATE')) || '';
        applyExtInDateRange(false);
    } else {
        Alert(Sepoa.cache.text.get("MESSAGE.1002"));
    }
});





var v = (ymd || '').replace(/[^0-9]/g, '');
if (v.length >= 8) {
    return v.substring(0, 4) + '-' + v.substring(4, 6) + '-' + v.substring(6, 8);
}
return ymd || '';




return (displayDate || '').replace(/[^0-9]/g, '').substring(0, 8);




if (smrStatus != 'RW') {
    return;
}
var smdNumber = getDocumentNumber("SPD"); // 관리번호(SSEDC.SMD_NUMBER에 저장)
var maxRowId = dhx4.newId();
var today = formatCertExtDate(sUtils.date.getToday());
var userName = Sepoa.info.NAME_LOC || Sepoa.info.USER_NAME_LOC || Sepoa.info.NAME || '';
var certName = '법인 공동인증서';
gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(today); // 일자
gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ')).setValue(String(gridObj.getRowsNum()));
gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(smdNumber); // 관리번호
gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_USER_ID')).setValue(Sepoa.info.ID);
gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_USER_NAME')).setValue(userName); // 담당자
gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_SUBJECT')).setValue(certName); // 공동인증서명
gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(''); // 설명
gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_NO')).setValue('');
gridObj.showRow(maxRowId);
$documentList[smdNumber] = {
    SMD_NUMBER: smdNumber,
    SMR_NUMBER: $reqExtInfo.SMR_NUMBER,
    ADD_DATE: toCertExtDateKey(today),
    SEAL_MG_SUBJECT: certName,
    ADD_USER_ID: Sepoa.info.ID,
    ADD_USER_NAME: userName
};




var header = this.getColumnId(ind);
if (header == 'ATTACH_IMG') {
    var attKey = gridObj.cells(rId, gridObj.getColIndexById('ATTACH_NO')).getValue();
    doAttachFile(rId, attKey);
}




var mode = 'NODEL'; // 업로드 가능, clear/삭제 숨김
if (smrStatus != 'RW') {
    mode = 'VI';
}
vaultPopup({
    attach_key: attach_key || '',
    type: 'CERTEXT_DOC',
    mode: mode,
    callback: setAttach_callback,
    rowId: rId,
    limit: 1
});




if (smrStatus != 'RW') {
    return;
}
// 설명(SUBJECT)에는 파일명을 넣지 않음
if (e.fileCount > 0) {
    if (e.attach_key) {
        gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_NO')).setValue(e.attach_key);
    }
    gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_IMG')).cell.style.filter = '';
    gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
    gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
} else if (e.uploaded === true) {
    gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_NO')).setValue(e.attach_key || '');
    gridObj.cells(r.rowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = '';
}




if (smrStatus != 'RW') {
    return;
}
var documentList = [];
gridObj.forEachRowA(function(id) {
    var row = {
        SMR_NUMBER: $reqExtInfo.SMR_NUMBER,
        SMD_NUMBER: gridObj.cells(id, gridObj.getColIndexById('SMD_NUMBER')).getValue(),
        SMR_SEQ: gridObj.cells(id, gridObj.getColIndexById('SMR_SEQ')).getValue(),
        ADD_DATE: toCertExtDateKey(gridObj.cells(id, gridObj.getColIndexById('DOC_NUMBER')).getValue()),
        ADD_USER_ID: gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_USER_ID')).getValue(),
        SEAL_MG_USER_ID: gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_USER_ID')).getValue(),
        SEAL_MG_SUBJECT: gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_SUBJECT')).getValue() || '법인 공동인증서',
        SUBJECT: gridObj.cells(id, gridObj.getColIndexById('SUBJECT')).getValue(),
        ATTACH_NO: gridObj.cells(id, gridObj.getColIndexById('ATTACH_NO')).getValue(),
        COUNT: '1',
        SEAL_TYPE: '',
        MANAGE_NUMBER: '',
        SEAL_MG_DEPT: ''
    };
    documentList.push(row);
});

var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res) {
            if (res.status == '1') {
                Alert(res.message || Sepoa.cache.text.get('MESSAGE.0001'));
                doQuery($reqExtInfo.SMR_NUMBER, moveFlag, editMode);
            } else {
                Alert(res.message || Sepoa.cache.text.get('MESSAGE.1002'));
            }
        }
    }
};
var params = {
    module: 'certext.req',
    action: 'doSaveDocumentList',
    CONNECTION: 'TRANSACTION',
    SMR_NUMBER: $reqExtInfo.SMR_NUMBER,
    PARAMETER: JSON.stringify({
        DOCUMENT_LIST: documentList
    })
};
sUtils.multipart.send(config, params);





dataOutput.setValue("SMR_NUMBER", smrNumber);

doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'CONNECTION', 'doQueryExtSelect', {
    SMR_NUMBER: smrNumber
}, function(so) {
    if (so.status == 1) {
        var sf = new SepoaFormater(so.result[0]);
        var sfList = sf.getArrayMap();
        if (sf.getRowCount() > 0) {
            var ListResult = sfList[0];

            dataOutput.setValue('COMPANY_CODE', ListResult.COMPANY_CODE);
            dataOutput.setValue('APP_NO', ListResult.APP_NO);
            dataOutput.setValue('APP_NO_SEQ', ListResult.APP_NO_SEQ);
            dataOutput.setValue('RE_FLAG', ListResult.RE_FLAG);
            dataOutput.setValue('APPLY_TYPE', ListResult.RE_FLAG);
            approval_grid.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'METHOD=getAppLine', 'PROCESS_ID=sepoa.svc.approval.SepoaApprovalService']);
        }
    } else {
        Alert(Sepoa.cache.text.get("MESSAGE.1002")); //오류발생
    }
});




if (count == 0) {
    Alert("결재자 정보를 조회하는데 실패하였습니다.");
} else {
    approval_grid.forEachRowA(function(id) {
        if (approval_grid.cells(id, approval_grid.getColIndexById('APP_LINE_STATUS')).getValue() == "") {
            approval_grid.cells(id, approval_grid.getColIndexById('APP_LINE_STATUS')).setValue("L06");
        }
    })
}




callFunction('p', 'doBack', []);




switch (editMode) {
    case "VIEW": // 뷰
        formObj.setViewMode(true);

        break;
    case "EDITOR": // 수정
        formObj.setViewMode(false);

        break;
    case "undefined": //doSave이후 화면이전시
        formObj.clear();
    default:
        break;
}




if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

if (!validateExtInDateWithinOneYear()) {
    return;
}

var formData = Object.assign(formObj.getFormData());
formData.REMARK = formObj.getValue('REMARK'); //사외반출 필요사유
formData.EXT_OUT_EXPECT_DATE = formObj.getValue('EXT_OUT_EXPECT_DATE'); // 예상사외반출일
formData.EXT_IN_EXPECT_DATE = formObj.getValue('EXT_IN_EXPECT_DATE'); // 예상사내반입일
formData.REJECT_REMARK = reject_comment; // 승인/반려사유
formData.EXT_USE_USER_ID = Sepoa.info.ID; // 반출 요청자(세션 ID)
$reqExtInfo = formData; // 반출 요청 정보(폼)

var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res) {
            if (res.status == "1") {
                if (callbackObj) { //임시저장이 아닌경우 callbackObj를 인자값으로 받음
                    callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
                } else {
                    Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                    if (moveFlag == 'Y') { //새로 만든 요청이라면 
                        linkTo('SPC_010', '/Public/CertExt/Request/PublicCertExtRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SPC_001.REQUEST_LIST'));
                        SUX.root.getContentsCell(window).close();
                    } else {
                        linkTo('SPC_010', '/Public/CertExt/Request/PublicCertExtRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SPC_001.REQUEST_LIST'));
                    }
                }
            } else {
                Alert(res.message);
            }
        }
    }
}

$reqExtInfo.APPLY_TYPE = 'CEXT'; // 공동인증서 반출
$reqExtInfo.APP_TYPE = 'E01'; // 공동인증서 반출 결재

// 반출 요청 정보(폼)
var serviceData = {
    REQ_EXT_INFO: $reqExtInfo
};

var params = {
    module: "certext.req",
    action: "doRequestService",
    CONNECTION: "TRANSACTION",
    CURRENT_PRC: "CREATE",
    SMR_NUMBER: formObj.getValue('SMR_NUMBER'),
    PARAMETER: JSON.stringify(serviceData)
}

if (callbackObj) { //임시저장이 아닐경우
    var callback_parm = callbackObj.CALLBACK_PARMETER;
    var return_logic_flag = callbackObj.RETURN_LOGIC_FLAG;
    if (return_logic_flag) {
        params['RETURN_LOGIC_FLAG'] = "Y";
    }

    sUtils.multipart.send(config, params);
} else { //임시저장
    Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE009'), function(flag) {
        if (flag) {
            sUtils.multipart.send(config, params);
        }
    });
}




// CertExt: MANAGER 단계 미사용




// CertExt: MANAGER 단계 미사용




// CertExt: MANAGER 단계 미사용




// CertExt: MANAGER 단계 미사용




// CertExt: MANAGER 단계 미사용




Confirm('반입신청을 진행하면 공동인증서 내역을 더 이상 첨부할 수 없습니다.\n반입신청을 진행하시겠습니까?', function(flag) {
    if (flag) {
        doSave({
            CALLBACK: doReturnProcess,
            CALLBACK_PARMETER: {
                LEGAL_PRC_TYPE: "RETURN_REQUEST",
            },
            RETURN_LOGIC_FLAG: true
        });
    }
});




Confirm(Sepoa.cache.text.get('SPC_001.MESSAGE_RETURN_COMPLETE'), function(flag) {
    if (flag) {
        doSave({
            CALLBACK: doReturnProcess,
            CALLBACK_PARMETER: {
                LEGAL_PRC_TYPE: "RETURN_COMPLETE"
            },
            RETURN_LOGIC_FLAG: true
        });
    }
});




var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res) {
            if (res.status == "1") {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                if (callbackParams.LEGAL_PRC_TYPE == "RETURN_REQUEST") {
                    linkTo('SPC_010', '/Public/CertExt/Request/PublicCertExtRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SPC_001.REQUEST_LIST'));
                } else {
                    linkTo('SPC_020', '/Public/CertExt/Todo/PublicCertExtTodoLayout.sux', 'undefined', Sepoa.cache.text.get('SPC_021.LAYOUT_A_HEADER'));
                }
            } else {
                Alert(res.message);
            }
        }
    }
}
var reqExtInfo = $reqExtInfo; //smr_number,폼데이터등의 정보
reqExtInfo.CONFIRM_STATUS = callbackParams.LEGAL_PRC_TYPE;

var serviceData = {
    REQ_EXT_INFO: $reqExtInfo
};

