if (!validateExtInDateWithinOneYear()) {
    return false;
}

var _fromTime = formObj.getValue('EXT_OUT_EXPECT_HOUR');
var _toTime = formObj.getValue('EXT_IN_EXPECT_HOUR');
if (_fromDate == _toDate && _fromTime >= _toTime) {
    Alert(Sepoa.cache.text.get('SPC_001.MSG_0003')); // 시간 입력이 잘못되었습니다.
    return false;
}

return true;




// Date / 표시문자열이어도 YYYYMMDD로 통일
if (v == null || v === '') {
    return '';
}
if (v instanceof Date) {
    if (isNaN(v.getTime())) {
        return '';
    }
    var yy = v.getFullYear();
    var mm = ('0' + (v.getMonth() + 1)).slice(-2);
    var dd = ('0' + v.getDate()).slice(-2);
    return '' + yy + mm + dd;
}
var s = String(v).replace(/[^0-9]/g, '');
return (s.length >= 8) ? s.substring(0, 8) : '';




// 반출예정일 + 1년 - 1일 (예: 20260720 -> 20270719)
var ymd = toYmd(outYmd);
if (!ymd) {
    return null;
}
var y = parseInt(ymd.substring(0, 4), 10);
var m = parseInt(ymd.substring(4, 6), 10) - 1;
var d = parseInt(ymd.substring(6, 8), 10);
var dt = new Date(y, m, d);
dt.setFullYear(dt.getFullYear() + 1);
dt.setDate(dt.getDate() - 1);
return toYmd(dt);




$extInDateRollback = true;
formObj.setValue('EXT_IN_EXPECT_DATE', $prevExtInExpectDate || '');
$extInDateRollback = false;




var outDate = toYmd(formObj.getValue('EXT_OUT_EXPECT_DATE'));
var inDate = toYmd(value != null ? value : formObj.getValue('EXT_IN_EXPECT_DATE'));

if (!inDate) {
    $prevExtInExpectDate = '';
    return;
}

if (!outDate) {
    Alert('사외반출일을 먼저 선택해 주세요.');
    rollbackExtInExpectDate();
    return;
}

if (inDate < outDate) {
    Alert(Sepoa.cache.text.get('MESSAGE.MSG_1002'));
    rollbackExtInExpectDate();
    return;
}

var maxInDate = getMaxExtInDate(outDate);
if (maxInDate && inDate > maxInDate) {
    Alert('선택할 수 없습니다. 사내반입일은 사외반출일 기준 1년 이내만 가능합니다.');
    rollbackExtInExpectDate();
    return;
}

$prevExtInExpectDate = inDate;




var outDate = toYmd(formObj.getValue('EXT_OUT_EXPECT_DATE'));
var inDate = toYmd(formObj.getValue('EXT_IN_EXPECT_DATE'));
var maxInDate = getMaxExtInDate(outDate);

if (fromOutChange && outDate && inDate) {
    if (inDate < outDate || (maxInDate && inDate > maxInDate)) {
        Alert('사외반출일 변경으로 사내반입일이 범위를 벗어났습니다. 사내반입일은 사외반출일 기준 1년 이내만 가능합니다.');
        $extInDateRollback = true;
        formObj.setValue('EXT_IN_EXPECT_DATE', '');
        $extInDateRollback = false;
        $prevExtInExpectDate = '';
    }
}




var outDate = toYmd(formObj.getValue('EXT_OUT_EXPECT_DATE'));
var inDate = toYmd(formObj.getValue('EXT_IN_EXPECT_DATE'));
if (!outDate || !inDate) {
    return true;
}
if (inDate < outDate) {
    Alert(Sepoa.cache.text.get('MESSAGE.MSG_1002'));
    return false;
}
var maxInDate = getMaxExtInDate(outDate);
if (maxInDate && inDate > maxInDate) {
    Alert('선택할 수 없습니다. 사내반입일은 사외반출일 기준 1년 이내만 가능합니다.');
    return false;
}
return true;




